"""Kilometersätze je Fahrtzweck in Cent."""

from __future__ import annotations

RATES_CENT = {
    "dienstlich": 30,
    "arbeitsweg": 30,
    "privat": 0,
}


def rate_for(purpose: str) -> int:
    return RATES_CENT[purpose]

touch.export/csv_export.py:
"""Fahrten und Abrechnungen als CSV, eine Zeile je Eintrag."""

from __future__ import annotations

import csv
import io

COLUMNS = ("Datum", "Fahrer", "km Start", "km Ende", "km", "Zweck", "Ziel", "Notiz")
SETTLEMENT_COLUMNS = ("Monat", "Fahrer", "Erstattung", "Pauschale", "Vorteil", "Auszahlung")


def _rows_to_csv(header, rows) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer, delimiter=";")
    writer.writerow(header)
    writer.writerows(rows)
    return buffer.getvalue()


def trips_to_csv(trips) -> str:
    return _rows_to_csv(COLUMNS, (
        (trip.day.isoformat(), trip.driver, trip.km_start, trip.km_end, trip.distance,
         trip.purpose, trip.destination, trip.note)
        for trip in trips))


def settlements_to_csv(settlements) -> str:
    return _rows_to_csv(SETTLEMENT_COLUMNS, (item.as_row() for item in settlements))

touch.fahrten/erfassung.py:
"""Fahrten aus der Monatsliste des Fahrers einlesen (CSV mit Semikolon).

Spalten: Datum (TT.MM.JJJJ), Fahrer, km Start, km Ende, Zweck, Ziel, Notiz. Leere Zeilen
und Zeilen, die mit `#` beginnen, werden übersprungen.
"""

from __future__ import annotations

import csv
import datetime as dt
import io

from fahrten.model import Trip


class RowError(ValueError):
    """Eine Zeile der Monatsliste ist nicht lesbar; `line` ist 1-basiert."""

    def __init__(self, line: int, reason: str):
        super().__init__(f"Zeile {line}: {reason}")
        self.line = line


def _parse_day(text: str) -> dt.date:
    return dt.datetime.strptime(text.strip(), "%d.%m.%Y").date()


def parse_row(row, line: int) -> Trip:
    if len(row) < 5:
        raise RowError(line, f"{len(row)} Spalten, erwartet mindestens 5")
    try:
        day = _parse_day(row[0])
        km_start, km_end = int(row[2]), int(row[3])
    except ValueError as exc:
        raise RowError(line, str(exc)) from None
    destination = row[5].strip() if len(row) > 5 else ""
    note = row[6].strip() if len(row) > 6 else ""
    return Trip(day, row[1].strip(), km_start, km_end, row[4].strip(), destination, note)


def read_trips(text: str) -> list[Trip]:
    trips = []
    for line, row in enumerate(csv.reader(io.StringIO(text), delimiter=";"), start=1):
        if not row or not "".join(row).strip() or row[0].lstrip().startswith("#"):
            continue
        trips.append(parse_row(row, line))
    return trips

touch.fahrten/model.py:
"""Eine Fahrt im Fahrtenbuch."""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass

PURPOSES = ("dienstlich", "privat", "arbeitsweg")


@dataclass(frozen=True)
class Trip:
    day: dt.date
    driver: str
    km_start: int
    km_end: int
    purpose: str
    destination: str = ""
    note: str = ""

    @property
    def distance(self) -> int:
        return self.km_end - self.km_start

    @property
    def month(self) -> str:
        return f"{self.day.year:04d}-{self.day.month:02d}"

    def is_business(self) -> bool:
        return self.purpose == "dienstlich"


def trips_in_month(trips, month: str) -> list[Trip]:
    """Fahrten eines Monats (`JJJJ-MM`), nach Tag und Anfangsstand sortiert."""
    selected = [trip for trip in trips if trip.month == month]
    return sorted(selected, key=lambda trip: (trip.day, trip.km_start))

touch.fahrten/pruefung.py:
"""Prüfungen des Fahrtenbuchs vor der Monatsabrechnung.

Das Finanzamt erkennt ein Fahrtenbuch nur an, wenn die Kilometerstände lückenlos
aneinander anschließen und jede dienstliche Fahrt ein Ziel nennt. Jede Prüfung liefert
eine Liste von Befunden; eine leere Liste heißt: nichts zu beanstanden.
"""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass

from fahrten.model import PURPOSES, Trip

MAX_DAILY_KM = 1500
MAX_BACKDATE_DAYS = 7


@dataclass(frozen=True)
class Finding:
    trip: Trip
    rule: str
    message: str

    def line(self) -> str:
        return f"{self.trip.day.isoformat()} {self.trip.driver}: {self.message} ({self.rule})"


def check_purpose(trip: Trip) -> list[Finding]:
    if trip.purpose not in PURPOSES:
        return [Finding(trip, "zweck", f"unbekannter Zweck {trip.purpose!r}")]
    return []


def check_distance(trip: Trip) -> list[Finding]:
    findings = []
    if trip.km_end < trip.km_start:
        findings.append(Finding(trip, "stand", "Endstand liegt unter dem Anfangsstand"))
    elif trip.distance == 0:
        findings.append(Finding(trip, "stand", "Fahrt ohne gefahrene Kilometer"))
    if trip.distance > MAX_DAILY_KM:
        findings.append(Finding(trip, "plausibel", f"mehr als {MAX_DAILY_KM} km an einem Tag"))
    return findings


def check_destination(trip: Trip) -> list[Finding]:
    if trip.is_business() and not trip.destination.strip():
        return [Finding(trip, "ziel", "dienstliche Fahrt ohne Ziel")]
    return []


def check_backdated(trip: Trip, recorded: dt.date) -> list[Finding]:
    """Ein Eintrag, der mehr als MAX_BACKDATE_DAYS nach der Fahrt erfasst wurde."""
    delay = (recorded - trip.day).days
    if delay > MAX_BACKDATE_DAYS:
        return [Finding(trip, "zeitnah", f"erst {delay} Tage nach der Fahrt erfasst")]
    return []


def check_sequence(trips) -> list[Finding]:
    """Kilometerstände müssen lückenlos und ohne Überlappung aufeinander folgen."""
    findings = []
    ordered = sorted(trips, key=lambda trip: (trip.day, trip.km_start))
    for previous, current in zip(ordered, ordered[1:]):
        if current.km_start > previous.km_end:
            gap = current.km_start - previous.km_end
            findings.append(Finding(current, "lücke", f"{gap} km zwischen zwei Fahrten fehlen"))
        elif current.km_start < previous.km_end:
            overlap = previous.km_end - current.km_start
            findings.append(Finding(current, "überlappung",
                                    f"überschneidet die vorige Fahrt um {overlap} km"))
    return findings


def check_drivers(trips, allowed) -> list[Finding]:
    allowed = {name.casefold() for name in allowed}
    return [Finding(trip, "fahrer", f"{trip.driver} ist nicht als Fahrer eingetragen")
            for trip in trips if trip.driver.casefold() not in allowed]


def check_trip(trip: Trip) -> list[Finding]:
    return check_purpose(trip) + check_distance(trip) + check_destination(trip)


def check_month(trips, allowed_drivers, recorded=None) -> list[Finding]:
    """Alle Prüfungen eines Monats; `recorded` ordnet Fahrten ihr Erfassungsdatum zu."""
    findings = []
    for trip in trips:
        findings.extend(check_trip(trip))
        if recorded and trip in recorded:
            findings.extend(check_backdated(trip, recorded[trip]))
    findings.extend(check_sequence(trips))
    findings.extend(check_drivers(trips, allowed_drivers))
    return sorted(findings, key=lambda f: (f.trip.day, f.trip.km_start, f.rule))


def summary(findings) -> dict[str, int]:
    """Anzahl der Befunde je Regel, für die Kopfzeile des Monatsberichts."""
    counts: dict[str, int] = {}
    for finding in findings:
        counts[finding.rule] = counts.get(finding.rule, 0) + 1
    return dict(sorted(counts.items()))


def blocking(findings) -> list[Finding]:
    """Befunde, ohne deren Klärung keine Abrechnung erstellt wird."""
    hard = {"stand", "lücke", "überlappung", "zweck"}
    return [finding for finding in findings if finding.rule in hard]

touch.kosten/abrechnung.py:
"""Monatsabrechnung je Fahrer.

Dienstliche Kilometer werden mit dem Kilometersatz erstattet, Arbeitswege über die
Entfernungspauschale je Arbeitstag, private Fahrten gehen als geldwerter Vorteil in die
Lohnabrechnung. Beträge rechnen durchgehend in Cent, gerundet wird erst in `euro()`.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field

from kosten.tarife import commute_cents, rate_for

PRIVATE_SHARE_CENT_PER_KM = 3


@dataclass
class DriverMonth:
    driver: str
    month: str
    business_km: int = 0
    private_km: int = 0
    commute_days: set = field(default_factory=set)
    trips: int = 0

    @property
    def total_km(self) -> int:
        return self.business_km + self.private_km


@dataclass(frozen=True)
class Settlement:
    driver: str
    month: str
    refund_cents: int
    commute_cents: int
    benefit_cents: int

    @property
    def payout_cents(self) -> int:
        return self.refund_cents + self.commute_cents

    def as_row(self) -> tuple:
        return (self.month, self.driver, euro(self.refund_cents), euro(self.commute_cents),
                euro(self.benefit_cents), euro(self.payout_cents))


def euro(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100},{cents % 100:02d} €"


def collect(trips) -> dict[tuple[str, str], DriverMonth]:
    """Kilometer und Arbeitstage je (Fahrer, Monat)."""
    months: dict[tuple[str, str], DriverMonth] = {}
    for trip in trips:
        key = (trip.driver, trip.month)
        entry = months.setdefault(key, DriverMonth(trip.driver, trip.month))
        entry.trips += 1
        if trip.purpose == "privat":
            entry.private_km += trip.distance
        elif trip.purpose == "arbeitsweg":
            entry.commute_days.add(trip.day)
        else:
            entry.business_km += trip.distance
    return months


def settle(entry: DriverMonth, one_way_km: int) -> Settlement:
    refund = entry.business_km * rate_for("dienstlich")
    commute = len(entry.commute_days) * commute_cents(one_way_km)
    benefit = entry.private_km * PRIVATE_SHARE_CENT_PER_KM
    return Settlement(entry.driver, entry.month, refund, commute, benefit)


def settle_month(trips, commute_km_by_driver) -> list[Settlement]:
    """Abrechnungen aller Fahrer eines Monats, nach Fahrer sortiert.

    `commute_km_by_driver` nennt je Fahrer die einfache Strecke zur Arbeit; ein Fahrer
    ohne Eintrag bekommt keine Entfernungspauschale.
    """
    settlements = []
    for (driver, _month), entry in sorted(collect(trips).items()):
        settlements.append(settle(entry, commute_km_by_driver.get(driver, 0)))
    return settlements


def totals(settlements) -> dict[str, int]:
    """Summen über alle Fahrer, für die Fußzeile des Berichts."""
    result = defaultdict(int)
    for item in settlements:
        result["refund"] += item.refund_cents
        result["commute"] += item.commute_cents
        result["benefit"] += item.benefit_cents
        result["payout"] += item.payout_cents
    return dict(result)


def compare(previous, current) -> dict[str, int]:
    """Veränderung der Auszahlung je Fahrer gegenüber dem Vormonat, in Cent."""
    before = {item.driver: item.payout_cents for item in previous}
    after = {item.driver: item.payout_cents for item in current}
    drivers = sorted(set(before) | set(after))
    return {driver: after.get(driver, 0) - before.get(driver, 0) for driver in drivers}

touch.kosten/budget.py:
"""Erstattungsbudget je Quartal und die Hochrechnung für den Rest des Quartals."""

from __future__ import annotations

from dataclasses import dataclass

QUARTER_MONTHS = 3


@dataclass(frozen=True)
class Budget:
    quarter: str
    limit_cents: int

    def used(self, settlements) -> int:
        return sum(item.payout_cents for item in settlements)

    def left(self, settlements) -> int:
        """Rest des Quartalsbudgets; negativ heißt überzogen."""
        return self.limit_cents - self.used(settlements)


def forecast(budget: Budget, settlements, months_done: int) -> int:
    """Hochrechnung der Auszahlung bis Quartalsende aus dem Schnitt der Monate bisher."""
    if months_done <= 0:
        return 0
    average = budget.used(settlements) // months_done
    return budget.used(settlements) + average * (QUARTER_MONTHS - months_done)


def warning(budget: Budget, settlements, months_done: int) -> str:
    expected = forecast(budget, settlements, months_done)
    if expected <= budget.limit_cents:
        return ""
    over = expected - budget.limit_cents
    return f"Quartal {budget.quarter}: Hochrechnung überschreitet das Budget um {over // 100} €"
